(function(){'use strict';
const M=window.NutriAssessment,$=id=>document.getElementById(id),names=['look','listen','ask','touch','report'],labels=['望','闻','问','切','体检'];let step=0,dirty=false,savedId=null,savedToken=null,savedWhen=null,urls={image:null,audio:null};
const say=t=>{$('status').textContent=t;};
for(const q of M.QUESTIONS){const label=document.createElement('label');label.textContent=q.label;const select=document.createElement('select');select.id='answer-'+q.id;for(const value of ['',...q.options]){const option=document.createElement('option');option.value=value;option.textContent=value||'跳过 / 暂不填写';select.append(option);}label.append(select);$('questions').append(label);}
function read(){const d=M.empty();for(const q of M.QUESTIONS)d.answers[q.id]=$('answer-'+q.id).value;d.feeling=$('feeling').value;d.voiceNote=$('voice-note').value;for(const k of Object.keys(d.report))d.report[k]=$('report-'+k).value;return M.normalize(d);}
function show(index,focus=false){step=index;names.forEach((name,i)=>{$('panel-'+name).hidden=i!==index;$('tab-'+name).setAttribute('aria-selected',String(i===index));$('tab-'+name).tabIndex=i===index?0:-1;});$('step-label').textContent=`${index+1} / 5 · ${labels[index]}`;$('previous').disabled=index===0;$('next').textContent=index===4?'生成文字摘要':'下一步 / 跳过';if(focus)$('tab-'+names[index]).focus();}
function release(kind){if(urls[kind])URL.revokeObjectURL(urls[kind]);urls[kind]=null;const prefix=kind==='image'?'photo':'audio',el=$(prefix+'-preview');if(kind==='audio')el.pause();el.removeAttribute('src');el.hidden=true;$(prefix+'-file').value='';$('remove-'+prefix).hidden=true;}
function selectFile(kind){const prefix=kind==='image'?'photo':'audio',file=$(prefix+'-file').files[0];if(!file)return;if(!M.validateFile(file,kind)){release(kind);say('请选择支持的文件格式，且大小在 10 MB 以内。');return;}if(urls[kind])URL.revokeObjectURL(urls[kind]);urls[kind]=URL.createObjectURL(file);$(prefix+'-preview').src=urls[kind];$(prefix+'-preview').hidden=false;$('remove-'+prefix).hidden=false;dirty=true;say('文件仅在当前页面预览，未上传或保存。');}
$('start').addEventListener('click',()=>{if(!$('entry-consent').checked){say('请先阅读并确认当前页面资料处理说明。');return;}$('consent-panel').hidden=true;$('workspace').hidden=false;show(0,true);say('可以逐项整理，也可以跳过没有资料的部分。');});
names.forEach((name,i)=>$('tab-'+name).addEventListener('click',()=>show(i)));
$('assessment-tabs').addEventListener('keydown',e=>{let n=step;if(e.key==='ArrowRight')n=(step+1)%5;else if(e.key==='ArrowLeft')n=(step+4)%5;else if(e.key==='Home')n=0;else if(e.key==='End')n=4;else return;e.preventDefault();show(n,true);});
$('previous').addEventListener('click',()=>show(Math.max(0,step-1),true));
$('next').addEventListener('click',()=>{if(step<4){show(step+1,true);return;}try{const text=M.summary(read());if(!text){say('还没有文字资料。你可以填写一项自述，也可以直接离开。');return;}if($('summary-text').value&&!window.confirm('重新生成将替换下方已编辑的文字摘要，继续吗？'))return;$('summary-text').value=text;$('summary-panel').hidden=false;$('save-consent').checked=false;dirty=true;$('summary-text').focus();say('请核对文字；当前尚未保存。');}catch(e){say(e.message);}});
$('workspace').addEventListener('input',e=>{dirty=true;if(e.target.id!=='save-consent')$('save-consent').checked=false;});
$('photo-file').addEventListener('change',()=>selectFile('image'));$('audio-file').addEventListener('change',()=>selectFile('audio'));
$('remove-photo').addEventListener('click',()=>{release('image');say('照片已从本页移除。');});$('remove-audio').addEventListener('click',()=>{release('audio');say('声音文件已从本页移除。');});
$('clear').addEventListener('click',()=>{if(!window.confirm('清空本次输入及文件预览？已保存到日历的摘要不会删除。'))return;release('image');release('audio');for(const q of M.QUESTIONS)$('answer-'+q.id).value='';for(const id of ['feeling','voice-note','summary-text',...Object.keys(M.empty().report).map(k=>'report-'+k)])$(id).value='';$('summary-panel').hidden=true;$('save-consent').checked=false;$('calendar-link').hidden=true;savedId=null;savedToken=null;savedWhen=null;dirty=false;show(0,true);say('本次草稿已清空。');});
$('save').addEventListener('click',()=>{if(!$('save-consent').checked){say('请先核对摘要，并确认仅保存到旧版本机日历。');return;}const text=$('summary-text').value.trim();if(!text||text.length>2000){say('请保留 1—2000 字的文字摘要。');return;}const C=window.NutriCalendar;if(!C?.saveAssessmentEntry){say('日历保存模块暂不可用，文字仍保留在当前页面。');return;}const now=new Date(),date=savedWhen?.date||C.dateKey(now),time=savedWhen?.time||String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');let result;try{result=C.saveAssessmentEntry(window.localStorage,{date,time,text,timeZone:savedWhen?.timeZone,id:savedId||undefined,expectedRecordToken:savedToken||undefined},true);}catch{result={ok:false,message:'本机存储不可用，摘要未保存。'};}if(!result.ok){say(result.message);return;}savedId=result.record.id;savedToken=result.recordToken;savedWhen={date:result.record.date,time:result.record.time,timeZone:result.record.timeZone};$('save-consent').checked=false;$('calendar-link').href='health-calendar.html?legacy=1&date='+encodeURIComponent(result.record.date);$('calendar-link').hidden=false;dirty=Boolean(urls.image||urls.audio);say('文字摘要已保存到旧版独立本机日历，不与 v3 合成账号互通；未生成体质或诊断结论。照片和声音文件没有保存。');});
for(const [kind,prefix] of [['image','photo'],['audio','audio']])$(prefix+'-preview').addEventListener('error',()=>{if(urls[kind]){release(kind);say('浏览器无法读取这个文件，预览已移除。可换一个文件或跳过。');}});
window.addEventListener('pageshow',e=>{if(e.persisted)window.location.reload();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('pagehide',()=>{release('image');release('audio');});
show(0);
})();
